    55→import org.thingsboard.server.service.security.model.ActivateUserRequest;
    56→import org.thingsboard.server.service.security.model.ChangePasswordRequest;
    57→import org.thingsboard.server.service.security.model.ResetPasswordEmailRequest;
    58→import org.thingsboard.server.service.security.model.ResetPasswordRequest;
    59→import org.thingsboard.server.service.security.model.SecurityUser;
    60→import org.thingsboard.server.service.security.model.UserPrincipal;
    61→import org.thingsboard.server.service.security.model.token.JwtTokenFactory;
    62→import org.thingsboard.server.service.security.system.SystemSecurityService;
    63→
    64→@RestController
    65→@TbCoreComponent
    66→@RequestMapping("/api")
    67→@Slf4j
    68→@RequiredArgsConstructor
    69→public class AuthController extends BaseController {
    70→
    71→    @Value("${server.rest.rate_limits.reset_password_per_user:5:3600}")
    72→    private String defaultLimitsConfiguration;
    73→    private final BCryptPasswordEncoder passwordEncoder;
    74→    private final JwtTokenFactory tokenFactory;
    75→    private final MailService mailService;
    76→    private final SystemSecurityService systemSecurityService;
    77→    private final SecuritySettingsService securitySettingsService;
    78→    private final RateLimitService rateLimitService;
    79→    private final ApplicationEventPublisher eventPublisher;
    80→    private final TwoFactorAuthService twoFactorAuthService;
    81→    private final RestAwareAuthenticationSuccessHandler authenticationSuccessHandler;
    82→
    83→    @ApiOperation(value = "Get current User (getUser)",
    84→            notes = "Get the information about the User which credentials are used to perform this REST API call.")
    85→    @PreAuthorize("hasAnyAuthority('SYS_ADMIN', 'TENANT_ADMIN', 'CUSTOMER_USER')")
    86→    @GetMapping(value = "/auth/user")
    87→    public User getUser() throws ThingsboardException {
    88→        SecurityUser securityUser = getCurrentUser();
    89→        User user = userService.findUserById(securityUser.getTenantId(), securityUser.getId());
    90→        checkDashboardInfo(user.getAdditionalInfo());
    91→        return user;
    92→    }
    93→
    94→    @ApiOperation(value = "Logout (logout)",
    95→            notes = "Special API call to record the 'logout' of the user to the Audit Logs. Since platform uses [JWT](https://jwt.io/), the actual logout is the procedure of clearing the [JWT](https://jwt.io/) token on the client side. ")
    96→    @PreAuthorize("hasAnyAuthority('SYS_ADMIN', 'TENANT_ADMIN', 'CUSTOMER_USER')")
    97→    @PostMapping(value = "/auth/logout")
    98→    public void logout(HttpServletRequest request) throws ThingsboardException {
    99→        logLogoutAction(request);
   100→    }
   101→
   102→    @ApiOperation(value = "Change password for current User (changePassword)",
   103→            notes = "Change the password for the User which credentials are used to perform this REST API call. Be aware that previously generated [JWT](https://jwt.io/) tokens will be still valid until they expire.")
   104→    @PreAuthorize("hasAnyAuthority('SYS_ADMIN', 'TENANT_ADMIN', 'CUSTOMER_USER')")
   105→    @PostMapping(value = "/auth/changePassword")
   106→    public JwtPair changePassword(@Parameter(description = "Change Password Request")
   107→                                  @RequestBody ChangePasswordRequest changePasswordRequest) throws ThingsboardException {
   108→        String currentPassword = changePasswordRequest.getCurrentPassword();
   109→        String newPassword = changePasswordRequest.getNewPassword();
   110→        SecurityUser securityUser = getCurrentUser();
   111→        UserCredentials userCredentials = userService.findUserCredentialsByUserId(TenantId.SYS_TENANT_ID, securityUser.getId());
   112→        if (!passwordEncoder.matches(currentPassword, userCredentials.getPassword())) {
   113→            throw new ThingsboardException("Current password doesn't match!", ThingsboardErrorCode.BAD_REQUEST_PARAMS);
   114→        }
   115→        systemSecurityService.validatePassword(newPassword, userCredentials);
   116→        if (passwordEncoder.matches(newPassword, userCredentials.getPassword())) {
   117→            throw new ThingsboardException("New password should be different from existing!", ThingsboardErrorCode.BAD_REQUEST_PARAMS);
   118→        }
   119→        userCredentials.setPassword(passwordEncoder.encode(newPassword));
   120→        userService.replaceUserCredentials(securityUser.getTenantId(), userCredentials);
   121→
   122→        eventPublisher.publishEvent(new UserCredentialsInvalidationEvent(securityUser.getId()));
   123→        return tokenFactory.createTokenPair(securityUser);
   124→    }
   125→
   126→    @ApiOperation(value = "Get the current User password policy (getUserPasswordPolicy)",
   127→            notes = "API call to get the password policy for the password validation form(s).")
   128→    @GetMapping(value = "/noauth/userPasswordPolicy")
   129→    public UserPasswordPolicy getUserPasswordPolicy() throws ThingsboardException {
   130→        SecuritySettings securitySettings = checkNotNull(securitySettingsService.getSecuritySettings());
   131→        return securitySettings.getPasswordPolicy();
   132→    }
   133→
   134→    @ApiOperation(value = "Check Activate User Token (checkActivateToken)",
   135→            notes = "Checks the activation token and forwards user to 'Create Password' page. " +
   136→                    "If token is valid, returns '303 See Other' (redirect) response code with the correct address of 'Create Password' page and same 'activateToken' specified in the URL parameters. " +
   137→                    "If token is not valid, returns '409 Conflict'. " +
   138→                    "If token is expired, redirects to error page.")
   139→    @GetMapping(value = "/noauth/activate")
   140→    public ResponseEntity<?> checkActivateToken(
   141→            @Parameter(description = "The activate token string.")
   142→            @RequestParam(value = "activateToken") String activateToken) {
   143→        UserCredentials userCredentials = userService.findUserCredentialsByActivateToken(TenantId.SYS_TENANT_ID, activateToken);
   144→        if (userCredentials == null) {
   145→            return response(HttpStatus.CONFLICT);
   146→        } else if (userCredentials.isActivationTokenExpired()) {
   147→            return redirectTo("/activationLinkExpired");
   148→        }
   149→        return redirectTo("/login/createPassword?activateToken=" + activateToken);
   150→    }
   151→
   152→    @ApiOperation(value = "Request reset password email (requestResetPasswordByEmail)",
   153→            notes = "Request to send the reset password email if the user with specified email address is present in the database. " +
   154→                    "Always return '200 OK' status for security purposes.")
   155→    @PostMapping(value = "/noauth/resetPasswordByEmail")
   156→    public void requestResetPasswordByEmail(
   157→            @Parameter(description = "The JSON object representing the reset password email request.")
   158→            @RequestBody ResetPasswordEmailRequest resetPasswordByEmailRequest,
   159→            HttpServletRequest request) throws ThingsboardException {
   160→        try {
   161→            String email = resetPasswordByEmailRequest.getEmail();
   162→            UserCredentials userCredentials = userService.requestPasswordReset(TenantId.SYS_TENANT_ID, email);
   163→            User user = userService.findUserById(TenantId.SYS_TENANT_ID, userCredentials.getUserId());
   164→            String baseUrl = systemSecurityService.getBaseUrl(user.getTenantId(), user.getCustomerId(), request);
   165→            String resetUrl = String.format("%s/api/noauth/resetPassword?resetToken=%s", baseUrl,
   166→                    userCredentials.getResetToken());
   167→
   168→            mailService.sendResetPasswordEmailAsync(resetUrl, userCredentials.getResetTokenTtl(), email);
   169→        } catch (Exception e) {
   170→            log.warn("Error occurred: {}", e.getMessage());
   171→        }
   172→    }
   173→
   174→    @ApiOperation(value = "Check password reset token (checkResetToken)",
   175→            notes = "Checks the password reset token and forwards user to 'Reset Password' page. " +
   176→                    "If token is valid, returns '303 See Other' (redirect) response code with the correct address of 'Reset Password' page and same 'resetToken' specified in the URL parameters. " +
   177→                    "If token is not valid, returns '409 Conflict'. " +
   178→                    "If token is expired, redirects to error page.")
   179→    @GetMapping(value = "/noauth/resetPassword")
   180→    public ResponseEntity<?> checkResetToken(
   181→            @Parameter(description = "The reset token string.")
   182→            @RequestParam(value = "resetToken") String resetToken) {
   183→        UserCredentials userCredentials = userService.findUserCredentialsByResetToken(TenantId.SYS_TENANT_ID, resetToken);
   184→        if (userCredentials == null) {
   185→            return response(HttpStatus.CONFLICT);
   186→        } else if (userCredentials.isResetTokenExpired()) {
   187→            return redirectTo("/passwordResetLinkExpired");
   188→        }
   189→        if (!rateLimitService.checkRateLimit(LimitedApi.PASSWORD_RESET, userCredentials.getUserId(), defaultLimitsConfiguration)) {
   190→            return response(HttpStatus.TOO_MANY_REQUESTS);
   191→        }
   192→        return redirectTo("/login/resetPassword?resetToken=" + resetToken);
   193→    }
   194→
   195→    @ApiOperation(value = "Activate User",
   196→            notes = "Checks the activation token and updates corresponding user password in the database. " +
   197→                    "Now the user may start using his password to login. " +
   198→                    "The response already contains the [JWT](https://jwt.io) activation and refresh tokens, " +
   199→                    "to simplify the user activation flow and avoid asking user to input password again after activation. " +
   200→                    "If token is valid, returns the object that contains [JWT](https://jwt.io/) access and refresh tokens. " +
   201→                    "If token is not valid, returns '400 Bad Request'.")
   202→    @PostMapping(value = "/noauth/activate")
   203→    public JwtPair activateUser(@Parameter(description = "Activate user request.")
   204→                                @RequestBody ActivateUserRequest activateRequest,
   205→                                @RequestParam(required = false, defaultValue = "true") boolean sendActivationMail,
   206→                                HttpServletRequest request) {
   207→        String activateToken = activateRequest.getActivateToken();
   208→        String password = activateRequest.getPassword();
   209→        systemSecurityService.validatePassword(password, null);
   210→        String encodedPassword = passwordEncoder.encode(password);
   211→        UserCredentials credentials = userService.activateUserCredentials(TenantId.SYS_TENANT_ID, activateToken, encodedPassword);
   212→        User user = userService.findUserById(TenantId.SYS_TENANT_ID, credentials.getUserId());
   213→        UserPrincipal principal = new UserPrincipal(UserPrincipal.Type.USER_NAME, user.getEmail());
   214→        SecurityUser securityUser = new SecurityUser(user, credentials.isEnabled(), principal);
   215→        userService.setUserCredentialsEnabled(user.getTenantId(), user.getId(), true);
   216→        String baseUrl = systemSecurityService.getBaseUrl(user.getTenantId(), user.getCustomerId(), request);
   217→        String loginUrl = String.format("%s/login", baseUrl);
   218→        String email = user.getEmail();
   219→
   220→        if (sendActivationMail) {
   221→            try {
   222→                mailService.sendAccountActivatedEmail(loginUrl, email);
   223→            } catch (Exception e) {
   224→                log.warn("Unable to send account activation email [{}]", e.getMessage());
   225→            }
   226→        }
   227→
   228→        JwtPair tokenPair;
   229→        if (twoFactorAuthService.isEnforceTwoFaEnabled(securityUser.getTenantId(), user)) {
   230→            tokenPair = authenticationSuccessHandler.createMfaTokenPair(securityUser, Authority.MFA_CONFIGURATION_TOKEN);
   231→        } else {
   232→            tokenPair = tokenFactory.createTokenPair(securityUser);
   233→        }
   234→
   235→        systemSecurityService.logLoginAction(user, new RestAuthenticationDetails(request), ActionType.LOGIN, null);
   236→        return tokenPair;
   237→    }
   238→
   239→    @ApiOperation(value = "Reset password (resetPassword)",
   240→            notes = "Checks the password reset token and updates the password. " +
   241→                    "If token is not valid, returns '400 Bad Request'.")
   242→    @PostMapping(value = "/noauth/resetPassword")
   243→    public void resetPassword(@Parameter(description = "Reset password request.")
   244→                                 @RequestBody ResetPasswordRequest resetPasswordRequest,
   245→                                 HttpServletRequest request) throws ThingsboardException {
   246→        String resetToken = resetPasswordRequest.getResetToken();
   247→        String password = resetPasswordRequest.getPassword();
   248→        UserCredentials userCredentials = userService.findUserCredentialsByResetToken(TenantId.SYS_TENANT_ID, resetToken);
   249→        if (userCredentials != null) {
   250→            if (userCredentials.isResetTokenExpired()) {
   251→                throw new ThingsboardException("Password reset token expired", ThingsboardErrorCode.BAD_REQUEST_PARAMS);
   252→            }
   253→            systemSecurityService.validatePassword(password, userCredentials);
   254→            if (passwordEncoder.matches(password, userCredentials.getPassword())) {
   255→                throw new ThingsboardException("New password should be different from existing!", ThingsboardErrorCode.BAD_REQUEST_PARAMS);
   256→            }
   257→            String encodedPassword = passwordEncoder.encode(password);
   258→            userCredentials.setPassword(encodedPassword);
   259→            userCredentials.setResetToken(null);
   260→            userCredentials.setResetTokenExpTime(null);
   261→            userCredentials = userService.replaceUserCredentials(TenantId.SYS_TENANT_ID, userCredentials);
   262→            User user = userService.findUserById(TenantId.SYS_TENANT_ID, userCredentials.getUserId());
   263→            UserPrincipal principal = new UserPrincipal(UserPrincipal.Type.USER_NAME, user.getEmail());
   264→            SecurityUser securityUser = new SecurityUser(user, userCredentials.isEnabled(), principal);
   265→            String baseUrl = systemSecurityService.getBaseUrl(user.getTenantId(), user.getCustomerId(), request);
   266→            String loginUrl = String.format("%s/login", baseUrl);
   267→            String email = user.getEmail();
   268→            try {
   269→                mailService.sendPasswordWasResetEmail(loginUrl, email);
   270→            } catch (Exception e) {
   271→                log.warn("Couldn't send password was reset email: {}", e.getMessage());
   272→            }
   273→
   274→            eventPublisher.publishEvent(new UserCredentialsInvalidationEvent(securityUser.getId()));
   275→        } else {
   276→            throw new ThingsboardException("Invalid reset token!", ThingsboardErrorCode.BAD_REQUEST_PARAMS);
   277→        }
   278→    }
   279→
   280→    private void logLogoutAction(HttpServletRequest request) throws ThingsboardException {
   281→        var user = getCurrentUser();
   282→        systemSecurityService.logLoginAction(user, new RestAuthenticationDetails(request), ActionType.LOGOUT, null);
   283→        eventPublisher.publishEvent(new UserSessionInvalidationEvent(user.getSessionId()));
   284→    }
   285→
   286→}
